<script lang="ts">
let {data,form}=$props();let edit=$state<any>(null);
const names:Record<string,string>={sell:'Sell Internet',vouchers:'Voucher inventory','voucher-batches':'Voucher batches',packages:'Internet packages',sales:'Cash sales','access-grants':'Access grants',reports:'Reports',staff:'Staff access',settings:'Settings / Omada'};
const descriptions:Record<string,string>={sell:'Reserve stock, confirm cash received, and hand over a voucher.',vouchers:'Keep track of every code, from available stock to expiry.','voucher-batches':'Prepare prepaid stock in batches. Generating stock is not revenue.',packages:'Simple, time-based access. One device per voucher.',sales:'An accurate record of cash received and safe reversals.','access-grants':'Entitlement and authorization history — not a live connection monitor.',reports:'Cash movement and stock, using Tanzania’s local day.',staff:'Control who can sell internet and administer your shop.',settings:'Private controller connectivity and explicit operating mode.'};
const money=(n:number)=>'TZS '+new Intl.NumberFormat('en-TZ').format(n||0);
const date=(d:string)=>d?new Intl.DateTimeFormat('en-TZ',{dateStyle:'medium',timeStyle:'short',timeZone:'Africa/Dar_es_Salaam'}).format(new Date(d)):'—';
const label=(s:string)=>s.replaceAll('_',' ').toLowerCase();
const admin=$derived(data.staff.role==='ADMIN');
const columns=$derived(data.section==='packages'?['name','price_tzs','duration_minutes','available','active']:data.section==='vouchers'?['code_mask','package_name','price_tzs','inventory_state','state']:data.section==='voucher-batches'?['label','quantity','created_at']:data.section==='sales'?['receipt_number','total_tzs','created_at']:data.section==='staff'?['display_name','role','enabled']:['code_mask','package_name','state','proposed_expires_at']);
function printPage(){window.print();}
</script>
<svelte:head><title>{names[data.section]} · {data.brand}</title></svelte:head>
<div class="page-heading no-print"><div><p class="eyebrow">{data.section==='sell'?'AT THE COUNTER':'SHOP WORKSPACE'}</p><h1>{names[data.section]}</h1><p>{descriptions[data.section]}</p></div>{#if data.section==='packages'&&admin}<button class="button" onclick={()=>edit={name:'',price_tzs:1000,duration_minutes:60,description:'',active:true}}>＋ New package</button>{/if}</div>
{#if form?.error}<div class="notice error no-print" role="alert">{form.error}</div>{/if}{#if form?.message}<div class="notice no-print" role="status">{form.message}</div>{/if}
{#if form?.printed}<section class="print-preview panel"><div class="no-print print-toolbar"><h2>Ready to print</h2><button class="button" onclick={printPage}>Print / Save as PDF</button></div>{#if form.sale}<div class="receipt"><p class="eyebrow">{data.brand}</p><h2>Cash sale receipt</h2><p class="small">{form.sale.receipt_number}</p><p>{date(form.sale.created_at)} · Cashier: {form.sale.cashier_name}</p><strong class="receipt-total">{money(form.sale.total_tzs)}</strong><p>{form.sale.items.length} voucher(s) · Paid by cash</p><p class="small muted">Application receipt. Not a certified fiscal or tax receipt.</p></div>{/if}<div class="voucher-sheet">{#each form.printed.items as v}<article class="printed-voucher"><p class="eyebrow">{data.brand}</p><h3>{v.package_name}</h3><strong class="voucher-code">{v.code}</strong><p>{v.duration_minutes} minutes · {money(v.price_tzs)}</p><p>Join the shop Wi-Fi and enter this code.</p><small>Validity starts at first activation. One device only. Time continues while disconnected.</small>{#if v.inventory_state==='AVAILABLE'}<span class="badge">Stock — must be sold before use</span>{/if}{#if v.inventory_state==='VOID'}<span class="badge">VOID — cannot be used</span>{/if}</article>{/each}</div></section>{/if}
{#if data.section==='sell'}
<div class="split no-print"><section class="panel"><p class="eyebrow">{form?.reservation?'STEP 2 · RECEIVE PAYMENT':'STEP 1 · SELECT STOCK'}</p><h2>{form?.reservation?'Confirm the cash sale':'Choose a package'}</h2>
{#if form?.reservation}<div class="sale-total"><span>{form.reservation.items.length} voucher(s)</span><strong>{money(form.reservation.total_tzs)}</strong><small>Reserved until {date(form.reservation.expires_at)}</small></div><ul class="line-items">{#each form.reservation.items as item}<li>{item.package_name}<strong>{money(item.price_tzs)}</strong></li>{/each}</ul><form method="POST"><input type="hidden" name="op" value="sell"><input type="hidden" name="reservation_id" value={form.reservation.id}><input type="hidden" name="idempotency_key" value={form.idempotency_key}><label>Customer name <small>Optional</small><input name="customer_name" maxlength="100"></label><label>Phone <small>Optional</small><input name="customer_phone" maxlength="30"></label><label>Notes <small>Optional</small><textarea name="notes" maxlength="500"></textarea></label><label class="checkbox"><input type="checkbox" name="cash_received" required>I have received {money(form.reservation.total_tzs)} in cash.</label><button class="button full">Record sale & prepare receipt →</button><a class="text-link" href="/sell">Start again (reservation releases after 5 minutes)</a></form>
{:else}<form method="POST"><input type="hidden" name="op" value="reserve"><label>Package<select name="package_id" required><option value="">Select a package</option>{#each data.packages.items as p}<option value={p.id} disabled={!p.available}>{p.name} · {money(p.price_tzs)} · {p.available} available</option>{/each}</select></label><label>Number of vouchers<input name="quantity" type="number" min="1" max="100" value="1" required></label><p class="small muted">Final prices come from the reserved vouchers. Existing stock keeps its original price after package edits.</p><button class="button full">Reserve stock →</button></form>{/if}</section><section class="panel accent"><p class="eyebrow">A SIMPLE HANDOVER</p><h2>Cash first.<br>Connection next.</h2><p>After recording the sale, print a receipt or share the voucher privately with the customer.</p><div class="rule"><strong>The clock hasn’t started yet.</strong><p>Validity begins when the customer first activates the code on their device.</p></div><p class="small">A reserved voucher is held for five minutes. Unsold codes cannot connect.</p></section></div>
{:else if data.section==='settings'}<div class="split"><section class="panel"><p class="eyebrow">OMADA EXTERNAL PORTAL</p><h2>{data.integration.mode==='mock'?'Simulation is enabled':'Live controller mode'}</h2><p>{data.integration.message}</p><dl class="details"><dt>Last connection check</dt><dd>{date(data.integration.last_check)}</dd><dt>Result</dt><dd>{data.integration.ok===null?'Not checked':data.integration.ok?'Login successful':'Check failed'}</dd><dt>Expiry</dt><dd>{data.integration.capabilities.expiry}</dd><dt>Disconnect / reconciliation</dt><dd>Unsupported</dd><dt>Packages</dt><dd>Time only · One device</dd></dl><form method="POST"><input type="hidden" name="op" value="test"><button class="button">Test operator login</button></form><p class="small muted">Login success does not verify real AP authorization or expiry.</p></section><section class="panel"><h2>Keep management private</h2><p>Controller credentials and the verified expiry profile are configured on the server. They are never sent to the browser.</p><p>Complete the commissioning checklist before serving paying customers in live mode.</p><p class="notice">Revoking a grant blocks future authorization. Existing network access may continue until the controller’s expiry.</p><h3>Brand & support</h3><p>{data.brand}</p><p class="small muted">Set WIFI_BRAND and WIFI_SUPPORT_CONTACT in the deployment environment.</p></section></div>
{:else if data.section==='reports'}<form class="filter-bar" method="GET"><label>From<input type="date" name="from" value={data.query.from||''}></label><label>To<input type="date" name="to" value={data.query.to||''}></label><button class="button secondary">Apply dates</button></form><div class="metrics financial"><article><span>Gross cash sales</span><strong>{money(data.totals.gross_tzs)}</strong></article><article><span>Reversals recorded</span><strong>{money(data.totals.reversals_tzs)}</strong></article><article><span>Net cash movement</span><strong>{money(data.totals.net_tzs)}</strong></article></div><section class="panel"><h2>Inventory right now</h2><div class="metrics"><article><span>Available</span><strong>{data.inventory.stock}</strong></article><article><span>Sold, unused</span><strong>{data.inventory.sold_unused}</strong></article><article><span>Active entitlements</span><strong>{data.inventory.active}</strong></article><article><span>Needs review</span><strong>{data.inventory.needs_review}</strong></article></div><p class="small muted">Sales use their sale date; reversals use their reversal date. Generated stock is excluded from revenue. Dates use Africa/Dar_es_Salaam.</p></section><section class="panel"><h2>Recent audit activity</h2><div class="table-wrap"><table><thead><tr><th>Action</th><th>Time</th></tr></thead><tbody>{#each data.audit.items as a}<tr><td>{label(a.action)}</td><td>{date(a.created_at)}</td></tr>{/each}</tbody></table></div></section>
{:else}
{#if data.section==='voucher-batches'}<section class="panel no-print"><h2>Generate stock</h2><form method="POST" class="inline-form"><input type="hidden" name="op" value="batch"><label>Package<select name="package_id" required><option value="">Choose package</option>{#each data.packages.items.filter((p:any)=>p.active) as p}<option value={p.id}>{p.name} · {money(p.price_tzs)}</option>{/each}</select></label><label>Quantity<input name="quantity" type="number" min="1" max="1000" value="10" required></label><label>Batch label <small>Optional</small><input name="label" placeholder="e.g. Saturday counter stock" maxlength="100"></label><button class="button">Generate vouchers</button></form></section>{/if}
{#if data.section==='staff'}<p class="notice">Create new staff securely with <code>pnpm staff:create</code>. There is no public registration. Disabling access takes effect on the next application request.</p>{/if}
{#if data.section==='packages'&&edit}<section class="panel no-print"><div class="print-toolbar"><h2>{edit.id?'Edit package':'New package'}</h2><button class="text-button" onclick={()=>edit=null}>Close</button></div><form method="POST"><input type="hidden" name="op" value="package"><input type="hidden" name="id" value={edit.id||''}><div class="form-grid"><label>Name<input name="name" value={edit.name} required maxlength="100"></label><label>Price (whole TZS)<input name="price_tzs" type="number" min="1" max="10000000" value={edit.price_tzs} required></label><label>Duration (minutes)<input name="duration_minutes" type="number" min="1" max="525600" value={edit.duration_minutes} required></label><label>Description<textarea name="description" maxlength="1000">{edit.description}</textarea></label></div><label class="checkbox"><input name="active" type="checkbox" checked={edit.active}>Active — allow new stock and sales</label><button class="button">Save package</button><p class="small muted">Existing vouchers retain their original package name, price and duration.</p></form></section>{/if}
<section class="panel list-panel no-print"><form method="GET" class="filter-bar"><label class="search-label"><span class="sr-only">Search records</span><input name="q" value={data.query.q||''} placeholder="Search records…"></label>{#if ['vouchers','access-grants'].includes(data.section)}<select name="state" aria-label="Filter by status"><option value="">All statuses</option>{#each ['AVAILABLE','SOLD','VOID','PENDING','ACTIVE','EXPIRED','REVOKED','NEEDS_REVIEW'] as state}<option value={state} selected={data.query.state===state}>{label(state)}</option>{/each}</select>{/if}<select name="sort" aria-label="Sort"><option value="newest">Newest first</option><option value="oldest" selected={data.query.sort==='oldest'}>Oldest first</option></select><button class="button secondary">Apply</button></form>
{#if data.list.items.length===0}<div class="empty"><span>◇</span><h2>No records to show</h2><p>{data.query.q||data.query.state?'Try changing your search or filters.':data.section==='packages'?'Create a package to prepare your first vouchers.':data.section==='sales'?'Your recorded cash sales will appear here.':'Records will appear here as your shop starts using the system.'}</p></div>{:else}<div class="table-wrap"><table><thead><tr>{#each columns as col}<th>{label(col)}</th>{/each}<th>Actions</th></tr></thead><tbody>{#each data.list.items as row}<tr>{#each columns as col}<td>{#if ['state','inventory_state','role'].includes(col)}<span class="badge" class:warning={row[col]==='NEEDS_REVIEW'}>{row[col]?label(row[col]):row.inventory_state==='SOLD'?'sold, unused':'—'}</span>{:else if col.endsWith('_tzs')}{money(row[col])}{:else if col.endsWith('_at')}{date(row[col])}{:else if typeof row[col]==='boolean'}{row[col]?'Yes':'No'}{:else if col==='receipt_number'}<a class="text-link" href={'/sales?sale='+row.id}>{row[col].slice(0,15)}…</a>{:else}{row[col]||'—'}{/if}</td>{/each}<td><div class="row-actions">
{#if data.section==='packages'&&admin}<button class="small-button" onclick={()=>edit={...row}}>Edit</button>{:else if data.section==='voucher-batches'}<form method="POST"><input type="hidden" name="op" value="print-batch"><input type="hidden" name="id" value={row.id}><button class="small-button">Print batch</button></form>{:else if data.section==='sales'}<form method="POST"><input type="hidden" name="op" value="print-sale"><input type="hidden" name="id" value={row.id}><button class="small-button">Print receipt</button></form>{#if admin}<details><summary>Reverse</summary><form method="POST" class="confirmation"><input type="hidden" name="op" value="reverse"><input type="hidden" name="id" value={row.id}><p>This permanently voids all codes. Only completely unused sales qualify.</p><label>Reason<textarea name="reason" minlength="3" maxlength="500" required></textarea></label><button class="button danger">Confirm reversal</button></form></details>{/if}{:else if data.section==='vouchers'&&admin}<form method="POST"><input type="hidden" name="op" value="reveal"><input type="hidden" name="id" value={row.id}><button class="small-button">Reveal</button></form>{#if row.inventory_state==='AVAILABLE'}<details><summary>Void</summary><form method="POST" class="confirmation"><input type="hidden" name="op" value="void"><input type="hidden" name="id" value={row.id}><p>This code will never be usable again.</p><label>Reason<textarea name="reason" minlength="3" maxlength="500" required></textarea></label><button class="button danger">Permanently void</button></form></details>{/if}{:else if data.section==='access-grants'&&row.state!=='REVOKED'}<details><summary>Revoke</summary><form method="POST" class="confirmation"><input type="hidden" name="op" value="revoke"><input type="hidden" name="id" value={row.id}><p>Blocks future authorization. Network access may continue until controller expiry.</p><label>Reason<textarea name="reason" minlength="3" maxlength="500" required></textarea></label><button class="button danger">Revoke access</button></form></details>{:else if data.section==='staff'&&row.id!==data.staff.id}<details><summary>Edit access</summary><form method="POST" class="confirmation"><input type="hidden" name="op" value="staff"><input type="hidden" name="id" value={row.id}><label>Role<select name="role"><option selected={row.role==='CASHIER'}>CASHIER</option><option selected={row.role==='ADMIN'}>ADMIN</option></select></label><label class="checkbox"><input type="checkbox" name="enabled" checked={row.enabled}>Enabled</label><button class="button">Save access</button></form></details>{/if}
</div></td></tr>{/each}</tbody></table></div>{/if}<div class="pagination"><span>Page {data.list.page} · Up to 25 records</span><div>{#if data.list.page>1}<a class="small-button" href={'?'+new URLSearchParams({...data.query,page:String(data.list.page-1)})}>← Previous</a>{/if}{#if data.list.has_more}<a class="small-button" href={'?'+new URLSearchParams({...data.query,page:String(data.list.page+1)})}>Next →</a>{/if}</div></div></section>
{#if data.sale}<section class="panel"><h2>Sale details</h2><p>{data.sale.receipt_number}</p><p>{date(data.sale.created_at)} · {data.sale.cashier_name}</p><strong>{money(data.sale.total_tzs)}</strong>{#if data.sale.reversal_reason}<p class="notice">Reversed: {data.sale.reversal_reason}</p>{/if}<ul>{#each data.sale.items as item}<li>{item.package_name} · {item.code_mask} · {money(item.price_tzs)}</li>{/each}</ul></section>{/if}
{#if data.attempts?.items.length}<section class="panel"><h2>Authorization needs review</h2><p>Verify the client’s authorization and deadline in the controller. Record evidence before deciding. Never assume a timeout means failure.</p>{#each data.attempts.items as attempt}<form method="POST" class="review-form"><input type="hidden" name="op" value="review"><input type="hidden" name="id" value={attempt.id}><p><strong>{attempt.evidence?.code}</strong> · Deadline: {date(attempt.deadline)}</p><label>Verified outcome<select name="decision"><option value="ACCEPTED">Controller confirms authorization</option><option value="REJECTED">Controller confirms no authorization</option></select></label><label>Evidence and reason<textarea name="reason" minlength="10" maxlength="500" required placeholder="Controller record, checked time, client and observed deadline"></textarea></label><button class="button secondary">Record verified outcome</button></form>{/each}</section>{/if}
{/if}
